import{_ as a,o as i,c as t,aj as e}from"./framework.js";const r=JSON.parse('{"title":"新建或克隆项目 | Cli / Getting Started | Documentation","description":"新建或克隆项目 in Kooboo: 新项目可以使用 kb new 创建远端站点并生成本地项目；已有站点使用 kb clone 拉取为本地项目。","frontmatter":{"title":"新建或克隆项目 | Cli / Getting Started | Documentation","description":"新建或克隆项目 in Kooboo: 新项目可以使用 kb new 创建远端站点并生成本地项目；已有站点使用 kb clone 拉取为本地项目。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cli/getting-started/create-or-clone.html"}]]},"headers":[],"relativePath":"zh/cli/getting-started/create-or-clone.md","filePath":"cli/getting-started/create-or-clone.md","lastUpdated":1784361314000}'),l={name:"zh/cli/getting-started/create-or-clone.md"};function n(h,s,p,o,d,c){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="新建或克隆项目" tabindex="-1">新建或克隆项目 <a class="header-anchor" href="#新建或克隆项目" aria-label="Permalink to &quot;新建或克隆项目&quot;">​</a></h1><p>新项目可以使用 <code>kb new</code> 创建远端站点并生成本地项目；已有站点使用 <code>kb clone</code> 拉取为本地项目。</p><h2 id="新建站点项目" tabindex="-1">新建站点项目 <a class="header-anchor" href="#新建站点项目" aria-label="Permalink to &quot;新建站点项目&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-site</span></span></code></pre></div><p>如果需要指定 Kooboo 服务器：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-site</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com</span></span></code></pre></div><p>执行过程中，CLI 会根据需要询问账号、密码、站点名称和项目模板。创建成功后，本地目录中会包含项目文件以及目标站点的环境配置。</p><p><code>kb new</code> 会创建远端站点。确认服务器地址和站点名称后再继续，避免在错误环境中产生新站点。</p><h2 id="克隆已有站点" tabindex="-1">克隆已有站点 <a class="header-anchor" href="#克隆已有站点" aria-label="Permalink to &quot;克隆已有站点&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com</span></span></code></pre></div><p>指定本地目录：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-site</span></span></code></pre></div><p>指定项目模板：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-site</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span></span></code></pre></div><p>不指定模板时，CLI 会交互式询问目标目录、项目能力和包管理器，并以空项目为基础完成克隆。克隆完成后，支持的站点资源和类型定义会写入本地项目。</p><h2 id="初始化本地项目" tabindex="-1">初始化本地项目 <a class="header-anchor" href="#初始化本地项目" aria-label="Permalink to &quot;初始化本地项目&quot;">​</a></h2><p>进入创建或克隆出的目录并安装依赖：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-site</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>然后检查 <code>.env</code>：</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">KOOBOO_SITE_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=https://example.com</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">KOOBOO_USERNAME</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=your-username</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">KOOBOO_PASSWORD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=your-password</span></span></code></pre></div><p>不要提交包含真实账号密码的 <code>.env</code>。</p><h2 id="创建与克隆的区别" tabindex="-1">创建与克隆的区别 <a class="header-anchor" href="#创建与克隆的区别" aria-label="Permalink to &quot;创建与克隆的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>远端结果</th><th>本地结果</th></tr></thead><tbody><tr><td><code>kb new</code></td><td>创建新站点</td><td>根据选择的模板生成项目</td></tr><tr><td><code>kb clone</code></td><td>不创建站点</td><td>拉取已有站点资源并生成项目</td></tr></tbody></table><p>克隆已有站点后，建议先运行 <code>git status</code> 并建立初始提交，再开始修改。新建项目准备首次发布时，先了解 <a href="./../workflows/push.html"><code>kb push</code></a> 和 <a href="./../workflows/sync.html"><code>kb sync --init</code></a> 的远端影响。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../project/resources.html">项目资源与目录</a></li><li><a href="./../workflows/pull.html">拉取远端资源</a></li><li><a href="./../workflows/push.html">推送本地资源</a></li></ul>`,26)])])}const g=a(l,[["render",n]]);export{r as __pageData,g as default};
